import{_ as i,c as t,o as s,ae as o}from"./chunks/framework.CliRSA9F.js";const a="/images/episode_visibility.webp",u=JSON.parse('{"title":"Episode Visibility","description":"","frontmatter":{},"headers":[],"relativePath":"features/episode-visibility.md","filePath":"features/episode-visibility.md"}'),r={name:"features/episode-visibility.md"};function n(l,e,d,h,p,g){return s(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="episode-visibility" tabindex="-1">Episode Visibility <a class="header-anchor" href="#episode-visibility" aria-label="Permalink to &quot;Episode Visibility&quot;">​</a></h1><h2 id="see-which-episodes-drive-your-organic-search-rankings" tabindex="-1">See Which Episodes Drive Your Organic Search Rankings <a class="header-anchor" href="#see-which-episodes-drive-your-organic-search-rankings" aria-label="Permalink to &quot;See Which Episodes Drive Your Organic Search Rankings&quot;">​</a></h2><p>Episode Visibility shows how individual episodes contribute to your podcast&#39;s search visibility. See which episodes rank for keywords on Apple Podcasts and Spotify, helping you understand which content drives discovery.</p><p>In the app, this is the <strong>episode view of the Organic Visibility tab</strong>. Open Organic Visibility in the Search Visibility navigation and switch to episode mode to reach this view; the show-level view of the same tab is covered in <a href="/features/show-visibility.html">Show Visibility</a>.</p><p><img src="'+a+'" alt="Episode Visibility Dashboard" width="600px" style="display:block;margin:0 auto;"></p><h2 id="what-you-ll-see" tabindex="-1">What You&#39;ll See <a class="header-anchor" href="#what-you-ll-see" aria-label="Permalink to &quot;What You&#39;ll See&quot;">​</a></h2><h3 id="summary-stats" tabindex="-1">Summary Stats <a class="header-anchor" href="#summary-stats" aria-label="Permalink to &quot;Summary Stats&quot;">​</a></h3><p>At the top of the view, a quick summary gives you the big picture at a glance:</p><ul><li><strong>Episode count</strong> - How many of your episodes have organic rankings</li><li><strong>Total rankings</strong> - The combined number of keyword rankings across all your episodes</li><li><strong>Top episode</strong> - The single episode driving the most rankings</li></ul><h3 id="episode-ranking-counts" tabindex="-1">Episode Ranking Counts <a class="header-anchor" href="#episode-ranking-counts" aria-label="Permalink to &quot;Episode Ranking Counts&quot;">​</a></h3><p>The main table lists your episodes with ranking counts for each platform:</p><ul><li><strong>Episode title</strong> - The episode being tracked</li><li><strong>Apple Podcasts count</strong> - Number of keywords this episode ranks for on Apple</li><li><strong>Spotify count</strong> - Number of keywords this episode ranks for on Spotify</li></ul><h3 id="sorting-your-episodes" tabindex="-1">Sorting Your Episodes <a class="header-anchor" href="#sorting-your-episodes" aria-label="Permalink to &quot;Sorting Your Episodes&quot;">​</a></h3><p>Reorder the list to surface what matters most. You can sort by:</p><ul><li><strong>Latest</strong> - Most recently published episodes first (the default)</li><li><strong>Total</strong> - Episodes with the most rankings first</li><li><strong>Alphabetical</strong> - By episode title</li><li><strong>Apple Podcasts</strong> - By Apple ranking strength</li><li><strong>Spotify</strong> - By Spotify ranking strength</li></ul><h3 id="loading-more-episodes" tabindex="-1">Loading More Episodes <a class="header-anchor" href="#loading-more-episodes" aria-label="Permalink to &quot;Loading More Episodes&quot;">​</a></h3><p>The list loads 25 episodes at a time. If you have a larger back catalog, use the &quot;load more&quot; option at the bottom of the list to bring in the next 25 episodes, continuing until your full catalog is displayed.</p><h3 id="keyword-details" tabindex="-1">Keyword Details <a class="header-anchor" href="#keyword-details" aria-label="Permalink to &quot;Keyword Details&quot;">​</a></h3><p>Click on any ranking count to see which specific keywords that episode ranks for. This reveals:</p><ul><li>The keyword terms the episode appears for</li><li>Ranking positions on each platform</li><li>How episode rankings differ from show-level rankings</li></ul><h2 id="understanding-episode-rankings" tabindex="-1">Understanding Episode Rankings <a class="header-anchor" href="#understanding-episode-rankings" aria-label="Permalink to &quot;Understanding Episode Rankings&quot;">​</a></h2><h3 id="how-episodes-rank-separately" tabindex="-1">How Episodes Rank Separately <a class="header-anchor" href="#how-episodes-rank-separately" aria-label="Permalink to &quot;How Episodes Rank Separately&quot;">​</a></h3><p>Podcast platforms sometimes rank individual episodes for search queries, especially when:</p><ul><li>The episode title closely matches the search term</li><li>The episode covers a specific topic the show doesn&#39;t focus on overall</li><li>The episode has strong engagement metrics</li></ul><h3 id="volatility-note" tabindex="-1">Volatility Note <a class="header-anchor" href="#volatility-note" aria-label="Permalink to &quot;Volatility Note&quot;">​</a></h3><p>Unlike show-level rankings which tend to be more stable, episode rankings can change frequently as platforms:</p><ul><li>Refresh their search indexes</li><li>Adjust ranking algorithms</li><li>Respond to engagement signals</li></ul><p>Check Episode Visibility periodically rather than expecting day-to-day consistency.</p><h2 id="using-episode-visibility-strategically" tabindex="-1">Using Episode Visibility Strategically <a class="header-anchor" href="#using-episode-visibility-strategically" aria-label="Permalink to &quot;Using Episode Visibility Strategically&quot;">​</a></h2><h3 id="identifying-your-discovery-engines" tabindex="-1">Identifying Your Discovery Engines <a class="header-anchor" href="#identifying-your-discovery-engines" aria-label="Permalink to &quot;Identifying Your Discovery Engines&quot;">​</a></h3><p>Find episodes that punch above their weight:</p><ul><li><strong>High ranking counts</strong> - Episodes appearing for many keywords are discovery engines</li><li><strong>Unique keywords</strong> - Episodes ranking for keywords your show doesn&#39;t rank for overall</li><li><strong>Strong performers</strong> - Episodes driving visibility in your key topics</li></ul><h3 id="content-strategy-insights" tabindex="-1">Content Strategy Insights <a class="header-anchor" href="#content-strategy-insights" aria-label="Permalink to &quot;Content Strategy Insights&quot;">​</a></h3><p>Learn what content drives rankings:</p><ul><li><strong>Title patterns</strong> - Do certain title formats rank better?</li><li><strong>Topic coverage</strong> - Which subjects generate the most episode-level rankings?</li><li><strong>Episode structure</strong> - Are longer or shorter episodes ranking differently?</li></ul><h3 id="optimization-opportunities" tabindex="-1">Optimization Opportunities <a class="header-anchor" href="#optimization-opportunities" aria-label="Permalink to &quot;Optimization Opportunities&quot;">​</a></h3><p>Use insights to improve future episodes:</p><ul><li><strong>Replicate success</strong> - Create more content similar to high-ranking episodes</li><li><strong>Fill gaps</strong> - Cover topics where only individual episodes rank</li><li><strong>Improve titles</strong> - Apply learnings from ranking episode titles to new content</li></ul><h2 id="difference-from-show-rankings" tabindex="-1">Difference from Show Rankings <a class="header-anchor" href="#difference-from-show-rankings" aria-label="Permalink to &quot;Difference from Show Rankings&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Feature</th><th>Show Visibility</th><th>Episode Visibility</th></tr></thead><tbody><tr><td>What it shows</td><td>Show-level keyword rankings</td><td>Episode-level keyword rankings</td></tr><tr><td>Stability</td><td>More stable over time</td><td>More volatile, changes frequently</td></tr><tr><td>View</td><td>Keywords with show rankings</td><td>Episodes with ranking counts</td></tr><tr><td>Use case</td><td>Overall SEO strategy</td><td>Content-level insights</td></tr></tbody></table><h2 id="integration-with-other-features" tabindex="-1">Integration with Other Features <a class="header-anchor" href="#integration-with-other-features" aria-label="Permalink to &quot;Integration with Other Features&quot;">​</a></h2><ul><li><strong>Show Visibility</strong> - See show-level rankings that complement episode data</li><li><strong>Show Rankings</strong> - Track specific keywords you&#39;re monitoring at the show level</li><li><strong>Episode Rankings</strong> - See your tracked keywords with episode-level ranking data</li></ul><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><p>Episode Visibility is available to Pro subscribers.</p><p><strong>Related Features</strong>: Use <a href="/features/show-visibility.html">Show Visibility</a> for show-level organic rankings, and <a href="/features/episode-rankings.html">Episode Rankings</a> to see how your tracked keywords perform at the episode level.</p>',45)])])}const y=i(r,[["render",n]]);export{u as __pageData,y as default};
